"""Render nine independently audited process/device/allocator observations."""
import hashlib,json,os
from pathlib import Path
D=Path(__file__).resolve().parent;B=D.parents[1];I=B/'e1_independent_review'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
a=D/'analysis001.json';p=I/'pixel_t020_nvml_execution_analysis_review.json';x=read(a);q=read(p);t=read(I/'monitor_pixel_t020_nvml_execution_analysis/terminal.json')
assert x['status']=='passed' and x['jobs']==9 and q['status']=='passed' and q['jobs']==9 and q['stages']==36 and q['analysis_sha256']==sha(a) and t['reason']=='completed' and t['worker_returncode']==0 and t['remaining_process_group']==[]
def mib(n):return 'unknown' if n is None else f'{n/1048576:.2f}'
txt=['# Pixel nine-process sampled memory pilot','','Nine isolated model processes cover three previously selected DEV anchors and three arms per anchor. `K` is the actual selected token count; runs have different workloads. Every process completed and all nine are reported. This is descriptive memory evidence, not TTFT, equal-compute comparison, or a population conclusion.','','For the phase rows, `process` is the maximum known sampled target-process NVML usage; `device` is the maximum known sampled whole-device usage. Both are MiB, accompanied by known/unknown observation counts. A target absent from NVML is unknown, not zero. Observations whose query windows overlap a phase can extend beyond that phase.','', '| Task | Arm | K | Phase | Overlap samples | Process max MiB (known/unknown) | Target absent | Device used max MiB (known/unknown) | Graphics PIDs observed |','|---|---|---:|---|---:|---:|---:|---:|---:|']
for r in x['results']:
 for name in ('pre_cuda','model_load','request','teardown'):
  s=r['stage_summary']['stages'][name];pm=s['overlap_metrics']['target'];dm=s['overlap_metrics']['used'];txt.append(f"| {r['job']['task']} | {r['job']['arm']} | {r['selected_count']} | {name} | {len(s['overlap_indices'])} | {mib(pm['max_known_bytes'])} ({pm['known']}/{pm['unknown']}) | {s['target_absent']} | {mib(dm['max_known_bytes'])} ({dm['known']}/{dm['unknown']}) | {len(s['graphics_pids'])} |")
txt+=['','PyTorch allocator values below are in MiB and are separate from both NVML columns. Model-load peaks are taken at load completion; request peaks follow a peak-stat reset before the request. Allocator measurements do not equal total process or device memory.','','| Task | Arm | K | Total NVML samples | Load allocated peak | Load reserved peak | Request allocated peak | Request reserved peak |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in x['results']:
 l=r['allocator_model_load'];v=r['allocator_request'];txt.append(f"| {r['job']['task']} | {r['job']['arm']} | {r['selected_count']} | {r['sample_count']} | {mib(l['allocated_peak_bytes'])} | {mib(l['reserved_peak_bytes'])} | {mib(v['allocated_peak_bytes'])} | {mib(v['reserved_peak_bytes'])} |")
txt+=['','NVML observations are approximately every 0.5 seconds, rounded to MiB, and can miss short-lived peaks. Graphics activity was present in the recorded windows; unobserved background remains unknown. Instrumentation, CPU copies and synchronization affect memory. Only three post-hoc anchors were studied; full prior visual intermediates were not all archived and identity relies partly on online capture checks. The raw records retain per-window indices, exact query boundaries, process/device inventories and all unknown counts.','',f'Complete machine-readable analysis: `analysis001.json` SHA256 `{sha(a)}`. Independent complete 36-phase recomputation: `../../e1_independent_review/pixel_t020_nvml_execution_analysis_review.json` SHA256 `{sha(p)}`. Independent nine-process raw result audit: `../../e1_independent_review/pixel_t020_nvml_execution_result_review.json` SHA256 `{sha(I/"pixel_t020_nvml_execution_result_review.json")}`.','']
with (D/'RESULT.md').open('x') as f:f.write('\n'.join(txt));f.flush();os.fsync(f.fileno())
